mapper.delete:
DELETE FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
AND primary_key = #{templateCode}

mapper.select:
SELECT primary_key as templateCode,
template_name,
user_code,
print_config,
enterprise_code
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND primary_key = #{templateCode}
AND delete_flag= 'f'
